   189  TcpOption TcpLayer::addTcpOptionAt(const TcpOptionBuilder& optionBuilder, int offset)
   190  {
   191          TcpOption newOption = optionBuilder.build();
   192          if (newOption.isNull())
   193                  return newOption;
   194
   195          // calculate total TCP option size
   196          TcpOption curOpt = getFirstTcpOption();
   197          size_t totalOptSize = 0;
   198          while (!curOpt.isNull())
   199          {
   200                  totalOptSize += curOpt.getTotalSize();
   201                  curOpt = getNextTcpOption(curOpt);
   202          }
   203          totalOptSize += newOption.getTotalSize();
   204
   205          size_t sizeToExtend = newOption.getTotalSize();
   206
   207          if (!extendLayer(offset, sizeToExtend))
   208          {
   209                  PCPP_LOG_ERROR("Could not extend TcpLayer in [" << sizeToExtend << "] bytes");
   210                  newOption.purgeRecordData();
   211                  return TcpOption(nullptr);
   212          }
   213
   214          memcpy(m_Data + offset, newOption.getRecordBasePtr(), newOption.getTotalSize());
   215
   216          newOption.purgeRecordData();
   217
   218          adjustTcpOptionTrailer(totalOptSize);
   219
   220          m_OptionReader.changeTLVRecordCount(1);
   221
   222          uint8_t* newOptPtr = m_Data + offset;
   223
   224          return TcpOption(newOptPtr);
   225  }
