   227  void TcpLayer::adjustTcpOptionTrailer(size_t totalOptSize)
   228  {
   229          int newNumberOfTrailingBytes = 0;
   230          while ((totalOptSize + newNumberOfTrailingBytes) % 4 != 0)
   231                  newNumberOfTrailingBytes++;
   232
   233          if (newNumberOfTrailingBytes < m_NumOfTrailingBytes)
   234                  shortenLayer(sizeof(tcphdr)+totalOptSize, m_NumOfTrailingBytes - newNumberOfTrailingBytes - 1);
   235          else if (newNumberOfTrailingBytes > m_NumOfTrailingBytes)
   236                  extendLayer(sizeof(tcphdr)+totalOptSize, newNumberOfTrailingBytes - m_NumOfTrailingBytes);
   237
   238          m_NumOfTrailingBytes = newNumberOfTrailingBytes;
   239
   240          for (int i = 0; i < m_NumOfTrailingBytes; i++)
   241                  m_Data[sizeof(tcphdr) + totalOptSize + i] = TCPOPT_DUMMY;
   242
   243          getTcpHeader()->dataOffset = (sizeof(tcphdr) + totalOptSize + m_NumOfTrailingBytes)/4;
   244  }
